"""Entry point executed INSIDE a Kaggle kernel (generated by scripts/kaggle/kaggle_job.py).

Reads the job JSON (substituted below at push time), copies the HyperDiscover source from the
private dataset input to /tmp, runs from source via PYTHONPATH (no pip build step), regenerates the
needed benchmark instances deterministically, runs the requested fits (scripts/run_many.py) or a
config sweep (scripts/run_sweep.py) on the kernel's GPUs, and packs everything into
/kaggle/working/results.tar.gz (one file: Kaggle caps output file counts). `kaggle_job.py pull`
downloads and unpacks it. The kernel exits non-zero if any fit or distillation failed.
"""

import json
import os
import shutil
import subprocess
import sys
import time
from pathlib import Path

JOB = json.loads(r"""__JOB_JSON__""")
WORK = Path("/kaggle/working")
REPO = Path("/tmp/hyperdiscover_src")  # NOT under /kaggle/working, to keep outputs small
OUT = Path("/tmp/hd_results")
BENCH = Path("/tmp/hd_bench")
MODULES = (
    "torch",
    "numpy",
    "scipy",
    "sympy",
    "networkx",
    "h5py",
    "pandas",
    "sklearn",
    "yaml",
    "matplotlib",
)


def find_source() -> Path:
    """Locate the uploaded source bundle (layout under /kaggle/input differs between Kaggle versions)."""
    hits = sorted(Path("/kaggle/input").rglob("pyproject.toml"), key=lambda p: len(p.parts))
    if not hits:
        print("contents of /kaggle/input:")
        for p in sorted(Path("/kaggle/input").rglob("*"))[:200]:
            print("  ", p)
        raise SystemExit("hyperdiscover source bundle not found under /kaggle/input")
    return hits[0].parent


def unpack_zips(root: Path) -> None:
    """`kaggle datasets create --dir-mode zip` stores sub-folders as <name>.zip; unpack them in place."""
    import zipfile

    for z in root.glob("*.zip"):
        target = root / z.stem
        if not target.exists():
            with zipfile.ZipFile(z) as fh:
                fh.extractall(target)


def setup() -> None:
    if REPO.exists():
        shutil.rmtree(REPO)
    shutil.copytree(find_source(), REPO)
    unpack_zips(REPO)
    os.environ["PYTHONPATH"] = str(REPO / "src") + os.pathsep + os.environ.get("PYTHONPATH", "")
    sys.path.insert(0, str(REPO / "src"))
    missing = []
    for mod in MODULES:
        try:
            __import__(mod)
        except ImportError:
            missing.append(mod)
    print("missing modules:", missing or "none", flush=True)
    if missing:  # best effort: works only when the kernel has internet
        names = {"yaml": "pyyaml", "sklearn": "scikit-learn"}
        subprocess.call(
            [sys.executable, "-m", "pip", "install", "-q", *[names.get(m, m) for m in missing]]
        )
    subprocess.call(
        [
            sys.executable,
            "-c",
            "import torch; print('torch', torch.__version__, 'cuda', "
            "torch.cuda.is_available(), [torch.cuda.get_device_name(i) for i in "
            "range(torch.cuda.device_count())])",
        ]
    )
    OUT.mkdir(parents=True, exist_ok=True)
    (OUT / "job.json").write_text(json.dumps(JOB, indent=2))
    with open(OUT / "check_env.txt", "w") as fh:  # Phase-0 style check on the kernel's GPU
        subprocess.call(
            [sys.executable, str(REPO / "scripts" / "check_env.py")],
            cwd=REPO,
            stdout=fh,
            stderr=subprocess.STDOUT,
        )


def run_sweep() -> int:
    return subprocess.call(
        [
            sys.executable,
            str(REPO / "scripts" / "run_sweep.py"),
            "--experiment",
            str(REPO / JOB["experiment"]),
            "--sweep",
            str(REPO / JOB["sweep"]),
            "--out",
            str(OUT / "sweep"),
            "--per-gpu",
            str(JOB.get("per_gpu", 4)),
            "--engine",
            JOB.get("engine", "library"),
        ],
        cwd=REPO,
    )


def run_grid() -> int:
    cmd = [
        sys.executable,
        str(REPO / "scripts" / "run_many.py"),
        "--grid",
        str(REPO / JOB["grid"]),
        "--bench-dir",
        str(BENCH),
        "--runs-dir",
        str(OUT / "runs"),
        "--start",
        str(JOB.get("start", 0)),
        "--per-gpu",
        str(JOB.get("per_gpu", 2)),
        "--threads",
        "2",
        f"--extra={JOB.get('extra', '')}",
    ]
    if JOB.get("count"):
        cmd += ["--count", str(JOB["count"])]
    rc = subprocess.call(cmd, cwd=REPO)
    if JOB.get("stage", "fit") == "all":  # CPU distillation in the same kernel
        for run in sorted((OUT / "runs").glob("*/seed0")):
            rc |= subprocess.call(
                [
                    sys.executable,
                    str(REPO / "scripts" / "run_pipeline.py"),
                    "--benchmark-file",
                    str(BENCH / f"{run.parent.name}.h5"),
                    "--stage",
                    "distill",
                    "--engine",
                    JOB.get("engine", "library"),
                    "--out",
                    str(run),
                ],
                cwd=REPO,
            )
    return rc


def run_baselines() -> int:
    """Generate the grid's benchmark files, then run the requested baselines on each (GPU for NRI)."""
    rc = subprocess.call(
        [
            sys.executable,
            str(REPO / "scripts" / "make_benchmark.py"),
            "--grid",
            str(REPO / JOB["grid"]),
            "--out",
            str(BENCH),
        ],
        cwd=REPO,
    )
    for f in sorted(BENCH.glob("*.h5")):
        rc |= subprocess.call(
            [
                sys.executable,
                str(REPO / "scripts" / "run_baselines.py"),
                "--benchmark-file",
                str(f),
                "--out",
                str(OUT / "baselines" / f.stem),
                "--methods",
                *JOB["baselines"],
                "--device",
                "cuda",
                "--nri-steps",
                str(JOB.get("nri_steps", 2000)),
            ],
            cwd=REPO,
        )
    return rc


def finish(rc: int, t0: float) -> None:
    """Record status, pack results into one archive, exit with rc."""
    (OUT / "kernel_done.json").write_text(
        json.dumps({"returncode": rc, "seconds": time.time() - t0})
    )
    shutil.copy2(OUT / "kernel_done.json", WORK / "kernel_done.json")
    shutil.make_archive(str(WORK / "results"), "gztar", root_dir=str(OUT))
    print("done", rc, f"{time.time() - t0:.0f}s", flush=True)
    sys.exit(rc)


def main():
    t0 = time.time()
    setup()
    if JOB.get("sweep"):
        rc = run_sweep()
    elif JOB.get("baselines"):
        rc = run_baselines()
    else:
        rc = run_grid()
    finish(rc, t0)


if __name__ == "__main__":
    main()
